        jdbc.update("UPDATE plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
        // from's crews become into's: crews from leads into leads; from's memberships move to into, unless
        // into is in that crew already or leads it.
        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", into.getId(), sheetId, from.getId());
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT m.crew_id FROM crew_member m WHERE m.person_id = ?)", sheetId, from.getId(), into.getId());
        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT c.id FROM crew c WHERE c.lead_id = ?)", sheetId, into.getId(), into.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
        withAliases(sheetId, List.of(into));
    }

    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
     *  statements dropped (the count back to 0) and their plans going with them; their holds, watchers, patron links (either way), pool
     *  and crew memberships (and crews they lead) and closed periods' fixed totals are dropped; they keep the sheet they came from as their
     *  origin. When {@code merging} (they are to be merged into someone there straight after) they keep
     *  their statements and arrive under a stand-in name, as theirs is taken there. Their claims must
     *  have moved first. */
    public void transfer(Person person, String to, boolean merging) {
        String sheetId = person.getSheetId();
        long id = person.getId();
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
        for (String table : List.of("person_hold", "person_watch", "pool_member", "crew_member")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        }
        // A crew they lead goes with its memberships.
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND crew_id IN (SELECT c.id FROM crew c WHERE c.lead_id = ?)",
                sheetId, id);
        jdbc.update("DELETE FROM crew WHERE sheet_id = ? AND lead_id = ?", sheetId, id);
        if (merging) {
            jdbc.update("UPDATE person_statement SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        } else {
            jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
            jdbc.update("UPDATE person SET statement_count = 0, stated_total = NULL, statement_date = NULL "
                    + "WHERE sheet_id = ? AND id = ?", sheetId, id);
        }
        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
        for (String table : List.of("person_grade", "person_grade_history", "person_retired_history", "person_retirement", "person_alias", "plan")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        }
        String name = merging ? "#merging-" + id : person.getName();
        jdbc.update("UPDATE person SET sheet_id = ?, name = ?, "
                + "origin = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?", to, name, sheetId, to, sheetId, id);
    }

    /** Swap the two people's places in their sheet's list. */
    public void swap(String sheetId, long a, long b) {
        Long posA = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, a);
        Long posB = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, b);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posB, sheetId, a);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posA, sheetId, b);
    }
}

    public void cloneSheet(String from, String to, String user, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets) {
        jdbc.update("INSERT INTO sheet (id, created_by, today) SELECT ?, ?, today FROM sheet WHERE id = ?",
                to, user, from);
        Map<String, Object> none = Map.of();
        for (String table : List.of("sheet_setting", "setting_history", "sheet_role", "rate", "rate_history", "rate_version",
                "holiday", "void_reason", "claim_template", "sheet_tag")) {
            copy(table, from, to, Map.of(), none);
        }
        Map<String, Object> unstated = new HashMap<>();
        unstated.put("statement_count", 0);
        unstated.put("stated_total", null);
        unstated.put("statement_date", null);
        unstated.put("version", 0);
        Map<Long, Long> people = copy("person", from, to, Map.of(), unstated);
        Map<String, Map<Long, Long>> byPerson = Map.of("person_id", people);
        for (String table : List.of("person_grade", "person_grade_history", "person_retired_history",
                "person_retirement", "person_hold", "person_alias")) {
            copy(table, from, to, byPerson, none);
        }
        copy("person_patron", from, to, Map.of("person_id", people, "patron_id", people), none);

        Map<Long, Long> pools = copy("pool", from, to, Map.of(), none);
        Map<String, Map<Long, Long>> members = new HashMap<>();
        members.put("pool_id", pools);
        members.put("person_id", people);
        members.put("member_pool_id", pools);
        copy("pool_member", from, to, members, none);

        Map<Long, Long> crews = copy("crew", from, to, Map.of("lead_id", people), none);
        copy("crew_member", from, to, Map.of("crew_id", crews, "person_id", people), none);

        Map<String, Object> open = new HashMap<>();
        open.put("closed", false);
        open.put("soft_closed", false);
        open.put("closed_total", null);
        open.put("closed_by", null);
        open.put("closed_at", null);
        copy("period", from, to, Map.of(), open);

package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

public class SavePerson {
    public void save(@RequestParam(name = "by", required = false) String by, @Val Person person,
            PersonRepository people) throws PersonConflictException {
        if (!people.update(person)) {
            throw new PersonConflictException(person.getId()); // saved by someone else meanwhile
        }
        if (person.getRecorded() != null) {
            people.saveGrade(person, person.getRecorded(), by == null ? "" : by);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded. */
public class RecordPersonEdited {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
    }
}

    /** The sheet's floor (two decimals) by date: a claim goes by the one in force on its date. */
    public DatedSetting floor(String sheetId) {
        return dated(sheetId, FLOOR, DEFAULT_FLOOR);
    }

    /** The terms (whole days) of a grade in force on a date: its own, else the sheet's (a null
     *  grade: the sheet's). */
    public int terms(String sheetId, String grade, String date) {
        String value = grade == null ? null : dated(sheetId, TERMS_OF_GRADE + grade, null).on(date);
        return Integer.parseInt(value != null ? value : dated(sheetId, TERMS, DEFAULT_TERMS).on(date));
    }

    /** The terms (whole days) of a claim of the person on a date: their own, else those of their
     *  grade in force on it, else the sheet's, each as in force on the date (a null person: the sheet's). */
    public int terms(String sheetId, net.officefloor.hq.app.person.Person person, String date) {
        if (person != null && person.getTerms() != null) {
            return person.getTerms();
        }
        return terms(sheetId, person == null ? null : person.gradeOn(date), date);
    }

    /** The sheet's late percent (two decimals) by date: a late charge goes by the one in force on each 30-day boundary. */
    public DatedSetting latePct(String sheetId) {
        return dated(sheetId, LATE_PCT, DEFAULT_LATE_PCT);
    }

