      name: v.person.name, grade: v.grade, gradeFrom: '', terms: v.person.terms === null ? '' : String(v.person.terms),
      contact: v.person.contact ?? '', tags: showTags(v.person.tags),
    }),
    onSuccess: (_, v) => {
      setGradePicks((d) => { const { [v.id]: _gone, ...rest } = d; return rest; });
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: tagsKey(sheetId) }),
    });
  };

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (p: Person) => {
    setForm({ name: p.name, grade: p.grade, gradeFrom: '', terms: p.terms === null ? '' : String(p.terms), contact: p.contact ?? '', tags: showTags(p.tags) });
    setEditing({ id: p.id, version: p.version });
    save.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  // Everyone's due-total as their row shows it (null: n/a), and their names, by id.
  const everyone = people.data ?? [];
