package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class AddPerson {
    public void add(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val PersonRequest request, SheetRepository sheets, PersonRepository people,
            Out<Person> person) throws InvalidPersonException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        if (people.nameTaken(id, request.name(), null) || people.nameTakenInTree(id, request.name())) {
            throw new InvalidPersonException("The name is already in use");
        }
        if (request.contact() != null && people.contactTaken(id, request.contact(), null)) {
            throw new InvalidPersonException("The contact is already in use");
        }
        sheets.open(id, user);
        person.set(people.add(id, request.name(), request.grade(),
                request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact(), request.tags(), user));
    }
}
            throws InvalidPersonException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PersonRequest> checked = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] f = line.split(",", 4);
            PersonRequest person = PersonForm.check(new PersonRequest(f[0], f.length > 1 ? f[1] : "", null,
                    f.length > 2 ? f[2] : "", null, f.length > 3 ? f[3] : "", null));
            if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                throw new InvalidPersonException("The name is repeated in the import: " + person.name());
            }
            if (person.contact() != null && !contacts.add(person.contact())) {
                throw new InvalidPersonException("The contact is repeated in the import: " + person.contact());
            }

